create table if not exists patient_duplicate_review_dispositions(target_patient_id text not null references patients(canonical_id),source_patient_id text not null references patients(canonical_id),status text not null check(status in ('pending','unique','reviewed')),note text,updated_at timestamptz not null default now(),primary key(target_patient_id,source_patient_id),check(target_patient_id<source_patient_id));
